	'messages:sort-descending' => 'ta:இறங்கு வரிசையில் வரிசைப்படுத்து',
	'messages:sort-ascending' => 'ta:ஏறுமுகமாக வரிசைப்படுத்து',
	'messages:sort-initial' => 'ta:தொடக்கத்தை வரிசைப்படுத்து',
	'messages:sort-rowspan-error' => 'ta:இந்தப் பக்கத்தில் rowspan பண்புக்கூறுடன் கூடிய அட்டவணை உள்ளது, இது அட்டவணையில் உள்ளதை விட அதிகமான வரிசைகளைக் கொண்டுள்ளது. பக்கத்தைத் திருத்துவதன் மூலம் இதைச் சரிசெய்யலாம்.',
	'messages:nstab-main' => 'ta:பக்கம்',
	'messages:nstab-user' => 'ta:{{GENDER:$1|பயனர் பெயர்}}:',
	'messages:nstab-media' => 'ta:ஊடகப் பக்கம்',
	'messages:nstab-special' => 'ta:சிறப்புப் பக்கம்',
