	'messages:ipboptions' => 'ta:2 மணிநேரம்:2 hours,1 நாள்:1 day,3 நாட்கள்:3 days,1 வாரம்:1 week,2 வாரங்கள்:2 weeks,1 மாதம்:1 month,3 மாதங்கள்:3 months,6 மாதங்கள்:6 months,1 ஆண்டு:1 year,முடிவிலி:infinite',
	'messages:ipbhidename' => 'ta:தொகுப்புகளிலும் பட்டியல்களிலுமிருந்து பயனர் பெயரை மறை',
	'messages:ipbwatchuser' => 'ta:இந்த பயனர்களின் பயனர் மற்றும் உரையாடல் பங்கங்களை கவனி.',
	'messages:ipb-disableusertalk' => 'ta:இந்த பயனர்கள் தடைசெய்யப்பட்டுள்ள போது தங்களுடைய உரையாடல் பக்கத்தைத் தொகுப்பதைத் தடுக்கவும்.',
	'messages:ipb-change-block' => 'ta:இந்த அமைப்புகளுடன் இப்பயனரை மீண்டும் தடுக்கவும்.',
	'messages:ipb-confirm' => 'ta:தடையை உறுதிசெய்',
	'messages:badipaddress' => 'ta:செல்லுபடியற்ற ஐ.பி. முகவரி',
	'messages:blockipsuccesssub' => 'ta:தடுப்பு வெற்றி',
	'messages:blockipsuccesstext' => 'ta:[[Special:Contributions/$1|$1]] தடுக்கப்பட்டுள்ளார்.<br />
தடுப்பை மறுஆய்வு செய்ய [[Special:BlockList|தடுப்பு பட்டியலைப்]] பார்கவும்.',
	'messages:ipb-blockingself' => 'ta:நீங்கள் உங்களையே தடுக்க முயல்கிறீர்கள்! உறுதியாக இதை செய்ய விரும்புகிறீர்களா?',
	'messages:ipb-confirmhideuser' => 'ta:"மறை பயனர்" இயக்கபட்ட பயனரை முடக்க விழைகிறீர்கள். இது அனைத்துப் பட்டியல் மற்றும் செயல்பாட்டு பதிவுகளில் பயனர் பெயரை ஒடுக்கும். நீங்கள் அதனை உறுதியாகச் செய்ய விரும்புகிறீர்களா?',
	'messages:ipb-confirmaction' => 'ta:நீங்கள் அதனை உறுதியாகச் செய்ய விரும்பினால், தயவுசெய்து கீழே உள்ள "{{int:ipb-confirm}}" பகுதியைத் தேர்ந்தெடுங்கள்.',
	'messages:ipb-edit-dropdown' => 'ta:தடை காரணங்கள் தொகு',
	'messages:ipb-unblock-addr' => 'ta:$1 இன் தடையை நீக்கு',
	'messages:ipb-unblock' => 'ta:ஐ.பி. அல்லது பயனருக்கான தடையை நீக்கு',
	'messages:ipb-blocklist' => 'ta:தற்போதுள்ள தடுப்புகளைப் பார்',
	'messages:ipb-blocklist-contribs' => 'ta:{{GENDER:$1|$1}}க்கு பங்களிப்புகள்',
	'messages:ipb-blocklist-duration-left' => 'ta:$1 வெளியேறினர்',
	'messages:block-expiry' => 'ta:காலாவதி:',
	'messages:unblockip' => 'ta:பயனர் தடையை நீக்கு',
	'messages:unblockiptext' => 'ta:முன்னர் தடுக்கப்பட்ட ஐ.பி. முகவரி அல்லது பயனர்பெயரின் எழுத்து அணுக்கத்தை மீழ்விப்பதற்கு கீழேயுள்ள படிவத்தை பயன்படுத்தவும்.',
	'messages:ipusubmit' => 'ta:இந்தத் தடையை நீக்கு',
	'messages:unblocked' => 'ta:[[User:$1|$1]] பயனருக்கான தடை நீக்கப்பட்டது',
	'messages:unblocked-range' => 'ta:$1 ஆனது தடைநீக்கப்பட்டது.',
	'messages:unblocked-id' => 'ta:$1 தடை நீக்கப்பட்டது',
	'messages:unblocked-ip' => 'ta:[[Special:Contributions/$1|$1]] முடக்கப்பட்டார்.',
	'messages:blocklist' => 'ta:தடைசெய்யப்பட்ட பயனர்கள்',
	'messages:autoblocklist' => 'ta:தன்னியக்கத் தடை',
	'messages:autoblocklist-submit' => 'ta:தேடு',
